// Build today's chasing list from the Invoices sheet. Emits tagged items:
//   action = "headsup"  -> due in 1-3 days, heads-up not yet sent
//   action = "due"      -> due today, due-date reminder not yet sent
//   action = "overdue3" -> 3-6 days overdue, firmer note not yet sent
//   action = "final"    -> 7+ days overdue, final notice not yet sent
//   action = "summary"  -> ONE item for the owner, Monday runs only
// Rows marked Paid / Cancelled / Written off are never chased. Each chase item
// arrives with its email subject and body already written, in the right tone.
const DAY_MS = 24 * 60 * 60 * 1000;
const items = $input.all();
if (!items.length) return [];
const cfg = items[0].json;
const startOfDay = (t) => { const d = new Date(t); d.setHours(0, 0, 0, 0); return d.getTime(); };
const today = startOfDay(Date.now());
const out = [];
const unpaid = [];
for (const item of items) {
  const j = item.json;
  const status = String(j['Status'] || '').trim().toLowerCase();
  if (status === 'paid' || status === 'cancelled' || status === 'written off') continue;
  const email = String(j['Email'] || '').trim();
  const due = new Date(j['Due Date']).getTime();
  if (!email.includes('@') || isNaN(due)) continue;
  const days = Math.round((startOfDay(due) - today) / DAY_MS); // + = days until due, - = days overdue
  const num = j['Invoice Number'];
  const first = String(j['Client Name'] || '').split(' ')[0] || 'there';
  const amount = (cfg.config_currency || '') + j['Amount'];
  const dueDate = j['Due Date'];
  const sent = (col) => String(j[col] || '').trim() !== '';
  let action = null, subject = '', body = '';
  if (days >= 1 && days <= 3 && !sent('Heads-Up Sent')) {
    action = 'headsup';
    subject = `A friendly heads-up: invoice ${num} is due on ${dueDate}`;
    body = `Hi ${first},\n\nJust a friendly heads-up from ${cfg.config_business_name}: invoice ${num} for ${amount} is due on ${dueDate} — ${days} day${days === 1 ? '' : 's'} from now.\n\nNo action needed if it is already in hand. If it helps, here is how to pay:\n${cfg.config_payment_instructions}\n\nThanks,\n${cfg.config_business_name}`;
  } else if (days === 0 && !sent('Due Reminder Sent')) {
    action = 'due';
    subject = `Due today: invoice ${num} (${amount})`;
    body = `Hi ${first},\n\nA short reminder that invoice ${num} for ${amount} from ${cfg.config_business_name} is due today, ${dueDate}.\n\nHow to pay:\n${cfg.config_payment_instructions}\n\nAlready paid? Thank you — please ignore this.\n\nBest,\n${cfg.config_business_name}`;
  } else if (days <= -3 && days >= -6 && !sent('Overdue 3 Sent')) {
    action = 'overdue3';
    subject = `Now ${-days} days overdue: invoice ${num} (${amount})`;
    body = `Hi ${first},\n\nInvoice ${num} for ${amount} was due on ${dueDate} and is now ${-days} days overdue. Our records may simply not have caught up — if you have paid, tell us and we will fix them today.\n\nIf not, please arrange payment now:\n${cfg.config_payment_instructions}\n\nIf something is wrong with the invoice itself, reply and tell us — we would rather sort it out than let it sit.\n\n${cfg.config_business_name}`;
  } else if (days <= -7 && !sent('Final Notice Sent')) {
    action = 'final';
    subject = `Final notice: invoice ${num} is ${-days} days overdue`;
    body = `Hi ${first},\n\nThis is the final automatic reminder for invoice ${num} (${amount}), due on ${dueDate} and now ${-days} days overdue.\n\nPlease pay today, or reply and agree a date with us:\n${cfg.config_payment_instructions}\n\nIf we do not hear back, we may pause ongoing work until the balance is cleared — we would much rather not.\n\n${cfg.config_business_name}`;
  }
  if (action) out.push({ json: { ...j, action, email_subject: subject, email_body: body } });
  unpaid.push({ num, amount: parseFloat(String(j['Amount']).replace(/[^0-9.]/g, '')) || 0, days, name: j['Client Name'] });
}
if (new Date().getDay() === 1 && unpaid.length) {
  const cur = cfg.config_currency || '';
  const total = unpaid.reduce((s, u) => s + u.amount, 0);
  const lines = unpaid
    .map(u => `- ${u.num} - ${u.name} - ${cur}${u.amount} - ${u.days >= 0 ? `due in ${u.days}d` : `${-u.days}d overdue`}`)
    .join('\n');
  out.push({ json: { action: 'summary',
    summary_text: `${unpaid.length} invoice(s) still unpaid, totalling ${cur}${total}:\n\n${lines}\n\nThe automatic chaser is working through them — your only job is to mark rows Paid as the money lands.`,
    summary_count: unpaid.length,
    config_owner_email: cfg.config_owner_email,
    config_business_name: cfg.config_business_name } });
}
return out;
